{
  "predictors": [
    {
      "name": "R&D Efficiency Ratio",
      "construction": "Total Sales (Compustat item 12) divided by R&D Expense (Compustat item 46), averaged over the last 3 fiscal years.",
      "rationale": "Companies that generate more sales per dollar of R&D expenditure may have more effective innovation processes, indicating potentially higher competitive advantages.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Dividend Consistency Score",
      "construction": "A score based on the consistency of dividend payments over the past 10 years, with higher scores for uninterrupted payments and consistent growth in dividends.",
      "rationale": "Firms with a strong track record of consistent dividends may signal financial stability and efficient capital management.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Compliance Ratio",
      "construction": "Environmental Compliance Expenses as a percentage of Total Operating Expenses, captured from industry reports and company filings.",
      "rationale": "Firms investing in compliance may avoid future regulatory costs and capture consumer preferences for sustainable practices.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Customer Concentration Risk",
      "construction": "Percentage of revenue derived from the top 3 customers, averaged over the last fiscal year, as reported in company filings.",
      "rationale": "Firms with lower customer concentration are less exposed to risks from losing a major customer, potentially leading to more stable future cash flows.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Insider Buy-Sell Ratio",
      "construction": "Ratio of insider purchases to insider sales, using data from Form 4 filings over the past 6 months.",
      "rationale": "High insider buying relative to selling may indicate confidence in the firm’s prospects by those with the most information.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patents per R&D Dollar",
      "construction": "Number of patents filed over the past 5 years divided by total R&D expenditure over the same period.",
      "rationale": "Firms that produce more patents per R&D dollar may be more efficient innovators, potentially leading to future growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supplier Dependence Index",
      "construction": "Proportion of cost of goods sold (COGS) from single-sourced suppliers, as a percentage of total COGS, averaged over the previous fiscal year.",
      "rationale": "Lower dependence on single suppliers may reduce supply chain risks and increase operational resilience.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Market Sentiment Index",
      "construction": "Net positive sentiment score derived from the tone of news articles mentioning the firm over the past year, using text analysis.",
      "rationale": "Positive sentiment in media may enhance brand reputation and investor confidence, potentially leading to higher returns.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Executive Tenure Stability",
      "construction": "Average tenure of top executives as listed in the firm’s proxy statements, measured in years.",
      "rationale": "Firms with stable executive teams may benefit from consistent leadership and strategic direction, supporting long-term performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Litigation Risk Exposure",
      "construction": "Count of lawsuits filed against the company in the past year, obtained from legal databases and company disclosures.",
      "rationale": "High litigation risk can lead to unpredictable costs and reputational damage, negatively impacting future returns.",
      "higher_returns_for": "low values of the measure"
    }
  ]
}
